import {downloadOffline} from './offline.js';
import {installObliqueViewer} from './volume-reslice.js';
export function volumeShape(m,axis){return axis==='z'?[m.width,m.height]:axis==='y'?[m.width,m.depth]:[m.height,m.depth];}
export function slicePixels(data,m,axis,index){if(!['x','y','z'].includes(axis))throw Error('Geçersiz düzlem');const count=axis==='x'?m.width:axis==='y'?m.height:m.depth;if(!Number.isInteger(index)||index<0||index>=count)throw Error('Kesit aralık dışında');if(data.length!==m.width*m.height*m.depth*3)throw Error('Hacim boyutu uyuşmuyor');const [w,h]=volumeShape(m,axis),out=new Uint8ClampedArray(w*h*4);for(let v=0;v<h;v++)for(let u=0;u<w;u++){const x=axis==='x'?index:u,y=axis==='z'?v:axis==='y'?index:u,z=axis==='z'?index:v,s=((z*m.height+y)*m.width+x)*3,t=(v*w+u)*4;out[t]=data[s];out[t+1]=data[s+1];out[t+2]=data[s+2];out[t+3]=255;}return{width:w,height:h,data:out};}
export function volumePoint(axis,u,v,current,m){const p={...current};if(axis==='z'){p.x=u;p.y=v;}else if(axis==='y'){p.x=u;p.z=v;}else{p.y=u;p.z=v;}for(const [k,max]of [['x',m.width],['y',m.height],['z',m.depth]])p[k]=Math.max(0,Math.min(max-1,Math.round(p[k])));return p;}
export class VolumeViewer{
 constructor(dialog){this.dialog=dialog;this.data=null;this.meta=null;this.abort=null;this.point=null;this.requestTicket=0;dialog.addEventListener('close',()=>{this.requestTicket++;this.abort?.abort();this.disposeOblique?.();this.fitObserver?.disconnect();this.space?.dispose();this.space=null;this.spaceTicket=(this.spaceTicket||0)+1;});}
 async open(){const ticket=++this.requestTicket;this.abort?.abort();this.disposeOblique?.();this.abort=new AbortController();if(!this.dialog.open)this.dialog.showModal();this.dialog.innerHTML='<button id="volumeClose" class="dialog-close" aria-label="Kesit hacmini kapat">×</button><h2>Gerçek anatomik kesit hacmi</h2><p>NLM Visible Human · Erkek göğüs bölgesinden renkli kesitler</p><div id="volumeBody"></div>';this.dialog.querySelector('#volumeClose').onclick=()=>this.dialog.close();if(this.data){this.controls();return;}this.dialog.querySelector('#volumeBody').innerHTML='<p>Veri bilgisi yükleniyor…</p>';try{this.meta=await fetch('./volume/manifest.json',{signal:this.abort.signal}).then(r=>{if(!r.ok)throw Error('Veri bilgisi alınamadı');return r.json();});if(ticket!==this.requestTicket||!this.dialog.open)return;this.dialog.querySelector('#volumeBody').innerHTML='<p>'+this.meta.depth+' ardışık kesit · kaynak aralığı '+this.meta.start+'–'+this.meta.end+'. İlk yüklemede yaklaşık '+Math.ceil(this.meta.bytes/1e6)+' MB indirilir.</p><button id="volumeLoad">Kesit hacmini yükle</button><p>Renkli doku fotoğraflarından oluşturulmuştur; BT/MR değildir. Düzlem görüntüleri aynı hacim içinde eşleşir. Atlasın GLB modeliyle hizalanmamıştır.</p>';this.dialog.querySelector('#volumeLoad').onclick=()=>this.load();}catch(e){if(ticket===this.requestTicket&&this.dialog.open&&e.name!=='AbortError')this.error(e.message);}}
 error(message){this.dialog.querySelector('#volumeBody').innerHTML='<p id="volumeError" role="alert"></p><button id="volumeRetry">Tekrar dene</button>';this.dialog.querySelector('#volumeError').textContent=message;this.dialog.querySelector('#volumeRetry').onclick=()=>this.open();}
 async load(){const ticket=++this.requestTicket;this.abort?.abort();const abort=this.abort=new AbortController();const current=()=>ticket===this.requestTicket&&this.dialog.open&&!abort.signal.aborted;this.dialog.querySelector('#volumeBody').innerHTML='<p id="volumeProgress" role="status">Hacim indiriliyor…</p>';try{if(typeof DecompressionStream==='undefined')throw Error('Bu tarayıcı sıkıştırılmış hacmi açamıyor. Güncel bir tarayıcı kullan.');const r=await fetch(this.meta.file,{signal:abort.signal});if(!r.ok)throw Error('Hacim dosyası indirilemedi');const reader=r.body.getReader(),chunks=[];let received=0;for(;;){const {value,done}=await reader.read();if(!current())return;if(done)break;chunks.push(value);received+=value.length;this.dialog.querySelector('#volumeProgress').textContent='İndiriliyor: '+Math.round(received/this.meta.bytes*100)+'%';}if(!current())return;this.dialog.querySelector('#volumeProgress').textContent='Kesitler hazırlanıyor…';const raw=await new Response(new Blob(chunks).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();if(raw.byteLength!==this.meta.uncompressedBytes)throw Error('Hacim dosyasının boyutu uyuşmuyor');if(globalThis.crypto?.subtle){const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',raw))].map(x=>x.toString(16).padStart(2,'0')).join('');if(hash!==this.meta.sha256)throw Error('Hacim bütünlük kontrolü başarısız');}if(!current())return;this.data=new Uint8Array(raw);this.point={x:Math.floor(this.meta.width/2),y:Math.floor(this.meta.height/2),z:Math.floor(this.meta.depth/2)};this.controls();}catch(e){if(e.name!=='AbortError'&&current())this.error(e.message);}}
 controls(){this.disposeOblique?.();this.fitObserver?.disconnect();this.space?.dispose();this.space=null;this.spaceTicket=(this.spaceTicket||0)+1;const m=this.meta;this.dialog.querySelector('#volumeBody').innerHTML='<button id="volumeSpaceOpen" aria-pressed="false">3B kesişim görünümünü aç</button><div id="volumeSpace" hidden></div><p id="volumeSpaceNote" hidden>Üç düzlem aynı fotoğraf hacminin koordinatlarındadır. Yeşil nokta 2B ve 3B görünümde aynıdır. Bu görünüm organ yüzey modeliyle eş-kayıt değildir. Sürükle: döndür · Dokun: nokta seç.</p><div class="volume-views">'+[['z','Aksiyel'],['y','Koronal yeniden kesit'],['x','Sagittal yeniden kesit']].map(([axis,name])=>'<section data-slice-card="'+axis+'"><h3>'+name+'</h3><div class="slice-frame"><canvas data-volume="'+axis+'" tabindex="0" aria-label="'+name+'; kesitte nokta seçmek için dokun, kaydırıcıyla düzlem değiştir"></canvas></div><p class="slice-size" data-slice-size="'+axis+'"></p><label>'+name+' konumu <output data-volume-value="'+axis+'"></output><input data-volume-range="'+axis+'" type="range" min="0" max="'+((axis==='x'?m.width:axis==='y'?m.height:m.depth)-1)+'"></label></section>').join('')+'</div><p id="volumeLocation" role="status"></p><p>Çizgiler aynı hacim içindeki kesişim noktasını gösterir. Görüntüye dokunarak diğer iki düzlemi o noktaya taşı.</p><details><summary>Kaynak, çözünürlük ve sınırlar</summary><p>'+m.depth+' ardışık kaynak kesit kullanıldı. Yatay çözünürlük '+m.width+' × '+m.height+' piksele düşürüldü; kesit aralığı '+m.spacingMm[2]+' mm. Görüntü içi piksel aralığı yaklaşık '+m.spacingMm[0].toFixed(2)+' mm.</p><p>Özgün görüntü yönleri korunmuştur; DICOM hasta yön matrisi yoktur. Kaynak kesit kaymaları düzeltilmedi. Hacim yalnızca seçili göğüs aralığını kapsar. Hücresel ayrıntı, tüm vücut, BT/MR ve GLB eş-kaydı içermez.</p><a href="'+m.source+'" target="_blank" rel="noreferrer">NLM kaynak serisi ↗</a></details><button id="volumeOffline">Gerçek kesitleri çevrimdışı sakla</button><p id="volumeCacheStatus" role="status">Bu hacim model indirmesinden ayrı saklanır.</p><button id="volumeUnload">Hacmi bellekten çıkar</button>';
 this.dialog.querySelector('#volumeOffline').onclick=async e=>{const b=e.target,status=this.dialog.querySelector('#volumeCacheStatus');b.disabled=true;status.textContent='Kesit verisi cihazda saklanıyor…';try{await downloadOffline('volume',(done,total)=>status.textContent=done+' / '+total+' dosya saklandı');status.textContent='Gerçek kesit hacmi çevrimdışı kullanım için saklandı.';}catch(err){status.textContent=err.message;}finally{b.disabled=false;}};this.installPlaneControls();this.dialog.querySelector('#volumeSpaceOpen').onclick=()=>this.toggleSpace();this.dialog.querySelectorAll('[data-volume-range]').forEach(el=>el.oninput=()=>{this.point[el.dataset.volumeRange]=Number(el.value);this.draw();});this.dialog.querySelectorAll('[data-volume]').forEach(canvas=>canvas.onclick=e=>{const box=canvas.getBoundingClientRect(),axis=canvas.dataset.volume,[w,h]=volumeShape(m,axis);this.point=volumePoint(axis,(e.clientX-box.left)/box.width*(w-1),(e.clientY-box.top)/box.height*(h-1),this.point,m);this.draw();});this.dialog.querySelector('#volumeUnload').onclick=()=>{this.space?.dispose();this.space=null;this.fitObserver?.disconnect();this.data=null;this.open();};installObliqueViewer(this);this.draw();}
 draw(){const m=this.meta,p=this.point;for(const axis of ['x','y','z']){const canvas=this.dialog.querySelector('[data-volume="'+axis+'"]'),slice=slicePixels(this.data,m,axis,p[axis]);canvas.width=slice.width;canvas.height=slice.height;const horizontal=axis==='x'?m.spacingMm[1]:m.spacingMm[0],vertical=axis==='z'?m.spacingMm[1]:m.spacingMm[2];canvas.dataset.physicalAspect=(slice.width*horizontal)/(slice.height*vertical);canvas.parentElement.style.aspectRatio=canvas.dataset.physicalAspect;this.dialog.querySelector('[data-slice-size="'+axis+'"]').textContent='Görüntü alanı: '+Math.round(slice.width*horizontal)+' × '+Math.round(slice.height*vertical)+' mm · Kaynak sınırlarının tamamı';const ctx=canvas.getContext('2d');ctx.putImageData(new ImageData(slice.data,slice.width,slice.height),0,0);const u=axis==='x'?p.y:p.x,v=axis==='z'?p.y:p.z;ctx.strokeStyle='#74ffd6';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(u+.5,0);ctx.lineTo(u+.5,slice.height);ctx.moveTo(0,v+.5);ctx.lineTo(slice.width,v+.5);ctx.stroke();this.dialog.querySelector('[data-volume-range="'+axis+'"]').value=p[axis];this.dialog.querySelector('[data-volume-value="'+axis+'"]').textContent=(p[axis]+1)+' / '+(axis==='x'?m.width:axis==='y'?m.height:m.depth);}this.dialog.querySelector('#volumeLocation').textContent='Kaynak kesit: a_vm'+(m.start+p.z)+' · Hacim koordinatı: '+p.x+', '+p.y+', '+p.z;this.fitImages();this.space?.update(p,Object.fromEntries(['x','y','z'].map(a=>[a,this.dialog.querySelector('[data-volume="'+a+'"]')])));}
 installPlaneControls(){
 const body=this.dialog.querySelector('#volumeBody'),views=body.querySelector('.volume-views');
 const tabs=document.createElement('div');tabs.className='volume-plane-tabs';tabs.setAttribute('role','group');tabs.setAttribute('aria-label','Görüntülenecek kesit düzlemi');tabs.innerHTML=[['z','Aksiyel'],['y','Koronal'],['x','Sagittal'],['all','Üçü birden']].map(([axis,label])=>'<button type="button" data-slice-plane="'+axis+'" aria-pressed="false">'+label+'</button>').join('');views.before(tabs);
 const extent=document.createElement('p');extent.id='volumeExtent';extent.textContent='Kaynak göğüs hacmi üst–alt yönde '+Math.round((this.meta.depth-1)*this.meta.spacingMm[2])+' mm kapsar. Koronal ve sagittal görünümler bu aralığın tamamını gösterir; gövdenin devamı bu veri içinde bulunmaz.';views.before(extent);
 const select=axis=>{views.dataset.plane=axis;tabs.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.slicePlane===axis)));views.querySelectorAll('[data-slice-card]').forEach(card=>card.hidden=axis!=='all'&&card.dataset.sliceCard!==axis);this.fitImages();};tabs.onclick=e=>{const b=e.target.closest('[data-slice-plane]');if(b)select(b.dataset.slicePlane);};select(globalThis.matchMedia?.('(max-width: 850px)').matches?'z':'all');
 this.dialog.querySelectorAll('[data-volume]').forEach(canvas=>canvas.onkeydown=e=>{const axes=canvas.dataset.volume==='z'?['x','y']:canvas.dataset.volume==='y'?['x','z']:['y','z'];const changes={ArrowLeft:[axes[0],-1],ArrowRight:[axes[0],1],ArrowUp:[axes[1],-1],ArrowDown:[axes[1],1]};if(!changes[e.key])return;e.preventDefault();const [axis,delta]=changes[e.key];this.point=volumePoint(canvas.dataset.volume,...(canvas.dataset.volume==='z'?[this.point.x+(axis==='x'?delta:0),this.point.y+(axis==='y'?delta:0)]:canvas.dataset.volume==='y'?[this.point.x+(axis==='x'?delta:0),this.point.z+(axis==='z'?delta:0)]:[this.point.y+(axis==='y'?delta:0),this.point.z+(axis==='z'?delta:0)]),this.point,this.meta);this.draw();});
 if(globalThis.ResizeObserver){this.fitObserver=new ResizeObserver(()=>this.fitImages());views.querySelectorAll('.slice-frame').forEach(frame=>this.fitObserver.observe(frame));}
 }
 fitImages(){for(const canvas of this.dialog.querySelectorAll('[data-volume]')){const box=canvas.parentElement.getBoundingClientRect(),aspect=Number(canvas.dataset.physicalAspect);if(!aspect||box.width<1||box.height<1)continue;const width=Math.min(box.width,box.height*aspect);canvas.style.width=width+'px';canvas.style.height=width/aspect+'px';canvas.style.aspectRatio=String(aspect);}}
 async toggleSpace(){const button=this.dialog.querySelector('#volumeSpaceOpen'),mount=this.dialog.querySelector('#volumeSpace');if(this.space){this.space.dispose();this.space=null;mount.hidden=true;this.dialog.querySelector('#volumeSpaceNote').hidden=true;button.textContent='3B kesişim görünümünü aç';button.setAttribute('aria-pressed','false');return;}button.disabled=true;const ticket=++this.spaceTicket;try{const {VolumeSpace}=await import('./volume-space.js');if(ticket!==this.spaceTicket||!this.dialog.open)return;mount.hidden=false;this.space=new VolumeSpace(mount,this.meta,p=>{this.point=p;this.draw();});this.dialog.querySelector('#volumeSpaceNote').hidden=false;button.textContent='3B görünümü kapat';button.setAttribute('aria-pressed','true');this.draw();}catch{mount.hidden=true;button.textContent='3B görünüm açılamadı · Tekrar dene';}finally{button.disabled=false;}}
}
